// JEI - Just Enough Items
// Author: vyrriox
//
// Translations live in JEI/stringtable.csv (generated by tools/gen_stringtable.py).
// Keys are STR_JEI_<KEY>; the game picks the column of the player's language.

class JEILang
{
	static string T(string key)
	{
		return Widget.TranslateString("#STR_JEI_" + key);
	}

	static string N(int value)
	{
		return value.ToString();
	}

	static string F(string key, string arg1)
	{
		return string.Format(T(key), arg1);
	}

	static string F2(string key, string arg1, string arg2)
	{
		return string.Format(T(key), arg1, arg2);
	}
}
